// ServerInterface represents all server handlers.
type ServerInterface interface {
	// List metal and alien machines (names and kinds only)
	// (GET /v1/credentials/machines)
	ListMachineCredentials(w http.ResponseWriter, r *http.Request)
	// Delete a machine's record
	// (DELETE /v1/credentials/machines/{name})
	DeleteMachineCredential(w http.ResponseWriter, r *http.Request, name Name)
	// A machine's manifest and credentials
	// (GET /v1/credentials/machines/{name})
	GetMachineCredential(w http.ResponseWriter, r *http.Request, name Name)
	// Store a machine's manifest and credentials, replacing any record
	// (PUT /v1/credentials/machines/{name})
	PutMachineCredential(w http.ResponseWriter, r *http.Request, name Name)
	// Delete a VM's credentials (whatever UUID they are for)
	// (DELETE /v1/credentials/vms/{host}/{name})
	DeleteVMCredential(w http.ResponseWriter, r *http.Request, host Host, name Name)
	// A VM's credentials, if the stored record is for this domain UUID
	// (GET /v1/credentials/vms/{host}/{name})
	GetVMCredential(w http.ResponseWriter, r *http.Request, host Host, name Name, params GetVMCredentialParams)
	// Store a VM's credentials, replacing any record for (host, name)
	// (PUT /v1/credentials/vms/{host}/{name})
	PutVMCredential(w http.ResponseWriter, r *http.Request, host Host, name Name)
	// A host daemon reports its full VM list
	// (PUT /v1/hosts/{host}/inventory)
	PutHostInventory(w http.ResponseWriter, r *http.Request, host Host)
	// The networks one host belongs to, with its peers' LAN addresses
	// (GET /v1/hosts/{host}/networks)
	GetHostNetworks(w http.ResponseWriter, r *http.Request, host Host)
	// List images, ordered by name
	// (GET /v1/images)
	ListImages(w http.ResponseWriter, r *http.Request)
	// Delete an image
	// (DELETE /v1/images/{name})
	DeleteImage(w http.ResponseWriter, r *http.Request, name Name)
	// One image's metadata
	// (GET /v1/images/{name})
	GetImage(w http.ResponseWriter, r *http.Request, name Name)
	// Upload an image, streamed
	// (PUT /v1/images/{name})
	PutImage(w http.ResponseWriter, r *http.Request, name Name, params PutImageParams)
	// Download an image's bytes, streamed
	// (GET /v1/images/{name}/blob)
	GetImageBlob(w http.ResponseWriter, r *http.Request, name Name)
	// Mint a download ticket for one image
	// (POST /v1/images/{name}/tickets)
	CreateImageTicket(w http.ResponseWriter, r *http.Request, name Name)
	// The store's inventory of hosts, VMs and machines
	// (GET /v1/inventory)
	GetInventory(w http.ResponseWriter, r *http.Request, params GetInventoryParams)
	// Remove a VM's inventory row at once
	// (DELETE /v1/inventory/{host}/{name})
	DeleteInventoryRow(w http.ResponseWriter, r *http.Request, host Host, name Name, params DeleteInventoryRowParams)
	// Mark a VM's live row gone
	// (POST /v1/inventory/{host}/{name}/delist)
	DelistVM(w http.ResponseWriter, r *http.Request, host Host, name Name)
	// Record a VM's origin, or set or clear its comment
	// (PUT /v1/inventory/{host}/{name}/notes)
	PutVMNotes(w http.ResponseWriter, r *http.Request, host Host, name Name)
	// The registered vmtool networks, with their members
	// (GET /v1/networks)
	ListNetworks(w http.ResponseWriter, r *http.Request)
	// Register a network and allocate its VNI and subnet
	// (POST /v1/networks)
	CreateNetwork(w http.ResponseWriter, r *http.Request)
	// Remove a network from the registry
	// (DELETE /v1/networks/{name})
	DeleteNetwork(w http.ResponseWriter, r *http.Request, name Name)
	// One registered network, with its members
	// (GET /v1/networks/{name})
	GetNetwork(w http.ResponseWriter, r *http.Request, name Name)
	// Remove a host from a network
	// (DELETE /v1/networks/{name}/members/{host})
	DeleteNetworkMember(w http.ResponseWriter, r *http.Request, name Name, host Host)
	// Add a host to a network, or update its LAN address
	// (PUT /v1/networks/{name}/members/{host})
	PutNetworkMember(w http.ResponseWriter, r *http.Request, name Name, host Host)
	// A network's recorded reservations
	// (GET /v1/networks/{name}/reservations)
	ListNetworkReservations(w http.ResponseWriter, r *http.Request, name Name)
	// Remove a recorded reservation
	// (DELETE /v1/networks/{name}/reservations/{mac})
	DeleteNetworkReservation(w http.ResponseWriter, r *http.Request, name Name, mac Mac)
	// Record a reservation of a network
	// (PUT /v1/networks/{name}/reservations/{mac})
	PutNetworkReservation(w http.ResponseWriter, r *http.Request, name Name, mac Mac)
	// The name of the calling token
	// (GET /v1/whoami)
	Whoami(w http.ResponseWriter, r *http.Request)
	// Reachability probe; public
	// (GET /version)
	GetVersion(w http.ResponseWriter, r *http.Request)
}

