type StrictServerInterface interface {
	// List metal and alien machines (names and kinds only)
	// (GET /v1/credentials/machines)
	ListMachineCredentials(ctx context.Context, request ListMachineCredentialsRequestObject) (ListMachineCredentialsResponseObject, error)
	// Delete a machine's record
	// (DELETE /v1/credentials/machines/{name})
	DeleteMachineCredential(ctx context.Context, request DeleteMachineCredentialRequestObject) (DeleteMachineCredentialResponseObject, error)
	// A machine's manifest and credentials
	// (GET /v1/credentials/machines/{name})
	GetMachineCredential(ctx context.Context, request GetMachineCredentialRequestObject) (GetMachineCredentialResponseObject, error)
	// Store a machine's manifest and credentials, replacing any record
	// (PUT /v1/credentials/machines/{name})
	PutMachineCredential(ctx context.Context, request PutMachineCredentialRequestObject) (PutMachineCredentialResponseObject, error)
	// Delete a VM's credentials (whatever UUID they are for)
	// (DELETE /v1/credentials/vms/{host}/{name})
	DeleteVMCredential(ctx context.Context, request DeleteVMCredentialRequestObject) (DeleteVMCredentialResponseObject, error)
	// A VM's credentials, if the stored record is for this domain UUID
	// (GET /v1/credentials/vms/{host}/{name})
	GetVMCredential(ctx context.Context, request GetVMCredentialRequestObject) (GetVMCredentialResponseObject, error)
	// Store a VM's credentials, replacing any record for (host, name)
	// (PUT /v1/credentials/vms/{host}/{name})
	PutVMCredential(ctx context.Context, request PutVMCredentialRequestObject) (PutVMCredentialResponseObject, error)
	// A host daemon reports its full VM list
	// (PUT /v1/hosts/{host}/inventory)
	PutHostInventory(ctx context.Context, request PutHostInventoryRequestObject) (PutHostInventoryResponseObject, error)
	// The networks one host belongs to, with its peers' LAN addresses
	// (GET /v1/hosts/{host}/networks)
	GetHostNetworks(ctx context.Context, request GetHostNetworksRequestObject) (GetHostNetworksResponseObject, error)
	// List images, ordered by name
	// (GET /v1/images)
	ListImages(ctx context.Context, request ListImagesRequestObject) (ListImagesResponseObject, error)
	// Delete an image
	// (DELETE /v1/images/{name})
	DeleteImage(ctx context.Context, request DeleteImageRequestObject) (DeleteImageResponseObject, error)
	// One image's metadata
	// (GET /v1/images/{name})
	GetImage(ctx context.Context, request GetImageRequestObject) (GetImageResponseObject, error)
	// Upload an image, streamed
	// (PUT /v1/images/{name})
	PutImage(ctx context.Context, request PutImageRequestObject) (PutImageResponseObject, error)
	// Download an image's bytes, streamed
	// (GET /v1/images/{name}/blob)
	GetImageBlob(ctx context.Context, request GetImageBlobRequestObject) (GetImageBlobResponseObject, error)
	// Mint a download ticket for one image
	// (POST /v1/images/{name}/tickets)
	CreateImageTicket(ctx context.Context, request CreateImageTicketRequestObject) (CreateImageTicketResponseObject, error)
	// The store's inventory of hosts, VMs and machines
	// (GET /v1/inventory)
	GetInventory(ctx context.Context, request GetInventoryRequestObject) (GetInventoryResponseObject, error)
	// Remove a VM's inventory row at once
	// (DELETE /v1/inventory/{host}/{name})
	DeleteInventoryRow(ctx context.Context, request DeleteInventoryRowRequestObject) (DeleteInventoryRowResponseObject, error)
	// Mark a VM's live row gone
	// (POST /v1/inventory/{host}/{name}/delist)
	DelistVM(ctx context.Context, request DelistVMRequestObject) (DelistVMResponseObject, error)
	// Record a VM's origin, or set or clear its comment
	// (PUT /v1/inventory/{host}/{name}/notes)
	PutVMNotes(ctx context.Context, request PutVMNotesRequestObject) (PutVMNotesResponseObject, error)
	// The registered vmtool networks, with their members
	// (GET /v1/networks)
	ListNetworks(ctx context.Context, request ListNetworksRequestObject) (ListNetworksResponseObject, error)
	// Register a network and allocate its VNI and subnet
	// (POST /v1/networks)
	CreateNetwork(ctx context.Context, request CreateNetworkRequestObject) (CreateNetworkResponseObject, error)
	// Remove a network from the registry
	// (DELETE /v1/networks/{name})
	DeleteNetwork(ctx context.Context, request DeleteNetworkRequestObject) (DeleteNetworkResponseObject, error)
	// One registered network, with its members
	// (GET /v1/networks/{name})
	GetNetwork(ctx context.Context, request GetNetworkRequestObject) (GetNetworkResponseObject, error)
	// Remove a host from a network
	// (DELETE /v1/networks/{name}/members/{host})
	DeleteNetworkMember(ctx context.Context, request DeleteNetworkMemberRequestObject) (DeleteNetworkMemberResponseObject, error)
	// Add a host to a network, or update its LAN address
	// (PUT /v1/networks/{name}/members/{host})
	PutNetworkMember(ctx context.Context, request PutNetworkMemberRequestObject) (PutNetworkMemberResponseObject, error)
	// A network's recorded reservations
	// (GET /v1/networks/{name}/reservations)
	ListNetworkReservations(ctx context.Context, request ListNetworkReservationsRequestObject) (ListNetworkReservationsResponseObject, error)
	// Remove a recorded reservation
	// (DELETE /v1/networks/{name}/reservations/{mac})
	DeleteNetworkReservation(ctx context.Context, request DeleteNetworkReservationRequestObject) (DeleteNetworkReservationResponseObject, error)
	// Record a reservation of a network
	// (PUT /v1/networks/{name}/reservations/{mac})
	PutNetworkReservation(ctx context.Context, request PutNetworkReservationRequestObject) (PutNetworkReservationResponseObject, error)
	// The name of the calling token
	// (GET /v1/whoami)
	Whoami(ctx context.Context, request WhoamiRequestObject) (WhoamiResponseObject, error)
	// Reachability probe; public
	// (GET /version)
	GetVersion(ctx context.Context, request GetVersionRequestObject) (GetVersionResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

